/** The adb trailer appended after `</hierarchy>`, typo and all. Not XML. Must be stripped. */
internal const val UIAUTOMATOR_DUMP_TRAILER: String = "UI hierchary dumped to: /dev/tty\n"

/** Byte sizes as captured, pinned so a corrupted or hand-edited fixture fails loudly. */
private object UiAutomatorDumpSizes {
    const val VIEW_BASED: Int = 26645
    const val COMPOSE: Int = 6142
    const val MID_SCROLL: Int = 28070
}

/**
 * Guards the fixtures themselves -- the smallest thing that fails if a dump is corrupted,
 * re-encoded or hand-edited on its way into git. There is no parser yet; T-3 adds it.
 */
class UiAutomatorDumpFixturesTest {

    private val dumps = listOf(
        Triple("VIEW_BASED_SETTINGS_DUMP", VIEW_BASED_SETTINGS_DUMP, UiAutomatorDumpSizes.VIEW_BASED),
        Triple("COMPOSE_APP_DUMP", COMPOSE_APP_DUMP, UiAutomatorDumpSizes.COMPOSE),
        Triple("MID_SCROLL_LIST_DUMP", MID_SCROLL_LIST_DUMP, UiAutomatorDumpSizes.MID_SCROLL),
    )

    @Test
    fun `every fixture is non-empty and still the exact byte size the device produced`() {
        dumps.forEach { (name, dump, bytes) ->
            assertTrue(dump.isNotEmpty(), "${'$'}name is empty -- no dump came back")
            assertEquals(bytes, dump.encodeToByteArray().size, "${'$'}name byte size drifted")
        }
    }

    @Test
    fun `every fixture is one well-formed hierarchy document followed only by the adb trailer`() {
        dumps.forEach { (name, dump, _) ->
            assertTrue(dump.startsWith("<?xml "), "${'$'}name does not start with an XML declaration")
            assertEquals(1, Regex("<hierarchy ").findAll(dump).count(), "${'$'}name root tag count")
            assertEquals(1, Regex("</hierarchy>").findAll(dump).count(), "${'$'}name root close count")
            val close = dump.indexOf("</hierarchy>") + "</hierarchy>".length
            assertEquals(UIAUTOMATOR_DUMP_TRAILER, dump.substring(close), "${'$'}name trailer")
        }
    }
}
